import java.util.*;

class Solution {
    public int minStickers(int[] scores) {
        int n = scores.length;
        int[] left = new int[n];
        Arrays.fill(left, 1);
        for (int i = 1; i < n; i++)
            if (scores[i] > scores[i - 1]) left[i] = left[i - 1] + 1;   // left-neighbour rule
        int total = 0, right = 1;
        for (int i = n - 1; i >= 0; i--) {
            if (i < n - 1 && scores[i] > scores[i + 1]) right++;         // right-neighbour rule
            else right = 1;
            total += Math.max(left[i], right);
        }
        return total;
    }
}

