class Solution:
    def minStickers(self, scores: List[int]) -> int:
        n = len(scores); c = [1] * n
        for i in range(1, n):
            if scores[i] > scores[i - 1]: c[i] = c[i - 1] + 1
        for i in range(n - 2, -1, -1):
            if scores[i] > scores[i + 1]: c[i] = max(c[i], c[i + 1] + 1)
        return sum(c)

