function minStickers(scores) {
  const n = scores.length, c = new Array(n).fill(1);
  for (let i = 1; i < n; i++) if (scores[i] > scores[i - 1]) c[i] = c[i - 1] + 1;
  for (let i = n - 2; i >= 0; i--) if (scores[i] > scores[i + 1]) c[i] = Math.max(c[i], c[i + 1] + 1);
  return c.reduce((a, b) => a + b, 0);
}
